import java.util.*; import java.io.*; public class TestClass { public static void main(String[] args) throws Exception { Scanner sc = new Scanner(System.in); if (!sc.hasNextInt()) return; int n = sc.nextInt(); int[] start = new int[n]; for (int i = 0; i < n; i++) start[i] = sc.nextInt(); int[] target = new int[n]; for (int i = 0; i < n; i++) target[i] = i + 1; if (Arrays.equals(start, target)) { System.out.println(0); return; } Queue<int[]> queue = new LinkedList<>(); Map<String, Integer> dist = new HashMap<>(); queue.add(start); dist.put(Arrays.toString(start), 0); while (!queue.isEmpty()) { int[] curr = queue.poll(); int d = dist.get(Arrays.toString(curr)); for (int i = 2; i <= n; i++) { int[] next = reverse(curr, i); String s = Arrays.toString(next); if (!dist.containsKey(s)) { if (Arrays.equals(next, target)) { System.out.println(d + 1); return; } dist.put(s, d + 1); queue.add(next); } } } } private static int[] reverse(int[] arr, int k) { int[] res = arr.clone(); int left = 0, right = k - 1; while (left < right) { int temp = res[left]; res[left] = res[right]; res[right] = temp; left++; right--; } return res; } }